  title?: string;
  height?: number;
} & (
  | { mode: 'sales'; sales: { series: SalesSeries[]; yAxisTitle?: string } }
  | { mode: 'monitoring'; monitoring: { timeline: number[]; series: MonitoringSeries[]; yAxisTitle?: string } }
);
